<?php

$finder = (new PhpCsFixer\Finder())
    ->in(__DIR__)
    ->exclude('var')
    ->exclude('vendor')
    // Application an earlier tests_e2e/run_e2e.sh built inside the repository
    // (it now builds it in a temporary directory); may still exist in a checkout.
    ->exclude('e2e-test')
    // Benchmark components generated by tests/Visual/ComponentGenerator.
    ->exclude('tests/Visual/Generated')
    ->exclude('tests/Integration/Fixtures')
;

return (new PhpCsFixer\Config())
    ->setRules([
        '@PSR12' => true,
        'array_syntax' => ['syntax' => 'short'],
        'no_unused_imports' => true,
    ])
    ->setFinder($finder)
;
